package org.marketreview.nativeapp;
import org.json.*;
import java.util.*;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;

final class WatchlistWorkspaceModel {
 static void need(boolean ok,String why)throws Exception{if(!ok)throw new Exception(why);}
 static String text(JSONObject o,String k)throws Exception{need(o.opt(k) instanceof String,k+"需明确文本");return o.getString(k);}
 static JSONObject object(Object...pairs)throws Exception{JSONObject o=new JSONObject();for(int i=0;i<pairs.length;i+=2)o.put((String)pairs[i],pairs[i+1]);return o;}
 static JSONObject copy(JSONObject o)throws Exception{return new JSONObject(o.toString());}
 static String quote(String s){StringBuilder b=new StringBuilder("\"");for(int i=0;i<s.length();i++){char c=s.charAt(i);switch(c){case '"':b.append("\\\"");break;case '\\':b.append("\\\\");break;case '\b':b.append("\\b");break;case '\f':b.append("\\f");break;case '\n':b.append("\\n");break;case '\r':b.append("\\r");break;case '\t':b.append("\\t");break;default:if(c<32)b.append(String.format(Locale.ROOT,"\\u%04x",(int)c));else b.append(c);}}return b.append('"').toString();}
 static String canonical(Object v)throws Exception{if(v==null||v==JSONObject.NULL)return "null";if(v instanceof Boolean)return v.toString();if(v instanceof String)return quote((String)v);if(v instanceof Number)return "@"+String.format(Locale.ROOT,"%016x",Double.doubleToRawLongBits(((Number)v).doubleValue()));List<String> parts=new ArrayList<>();if(v instanceof JSONArray){JSONArray a=(JSONArray)v;for(int i=0;i<a.length();i++)parts.add(canonical(a.get(i)));return "["+String.join(",",parts)+"]";}need(v instanceof JSONObject,"不支持的配置值");JSONObject o=(JSONObject)v;List<String> keys=new ArrayList<>();o.keys().forEachRemaining(keys::add);Collections.sort(keys);for(String k:keys)parts.add(quote(k)+":"+canonical(o.get(k)));return "{"+String.join(",",parts)+"}";}
 static String hash(Object v)throws Exception{byte[]d=MessageDigest.getInstance("SHA-256").digest(canonical(v).getBytes(StandardCharsets.UTF_8));StringBuilder b=new StringBuilder();for(byte x:d)b.append(String.format(Locale.ROOT,"%02x",x&255));return b.toString();}
 static boolean equal(Object a,Object b)throws Exception{return canonical(a).equals(canonical(b));}
 static boolean fullId(String id){return id.matches("(SH|SZ|BJ):(stock|index|etf):[0-9]{6}");}
 static void label(String s)throws Exception{need(!s.trim().isEmpty()&&s.equals(s.trim())&&s.length()<=60&&!s.matches("(?s).*[\\x00-\\x1f\\x7f].*"),"名称需1至60字且无首尾空格或控制字符");}
 static void color(String s)throws Exception{need(s.isEmpty()||s.matches("#[0-9A-Fa-f]{6}"),"识别色需空或#RRGGBB");}
 static Set<String> ids(Object value,boolean instrument)throws Exception{need(value instanceof JSONArray,"成员清单缺失");JSONArray a=(JSONArray)value;need(a.length()<=3000,"成员超过3000");Set<String> set=new HashSet<>();for(int i=0;i<a.length();i++){Object v=a.get(i);need(v instanceof String,"成员身份需文本");String id=(String)v;need(!id.isEmpty()&&(!instrument||fullId(id))&&set.add(id),"成员身份无效或重复");}return set;}
 static JSONObject validate(JSONObject s)throws Exception{need(text(s,"schema").equals("watchlist-workspace/v1"),"快照格式不支持");String revision=text(s,"revision");need(!revision.trim().isEmpty()&&revision.length()<=256,"需明确管理配置版本");need(s.opt("instruments") instanceof JSONArray&&s.opt("groups") instanceof JSONArray,"完整目录或分组缺失");Set<String> primary=ids(s.opt("mainIds"),true),roster=new HashSet<>();JSONArray instruments=s.getJSONArray("instruments");need(instruments.length()<=3000,"完整目录超过3000");for(int i=0;i<instruments.length();i++){JSONObject r=instruments.getJSONObject(i);String id=text(r,"id"),name=text(r,"name");need(fullId(id)&&roster.add(id)&&!Boolean.TRUE.equals(r.opt("transient")),"目录身份重复或临时观察不可提升");need(!name.trim().isEmpty()&&name.length()<=128,"目录名称无效");if(r.has("symbol")){String[]p=id.split(":");need(text(r,"symbol").equals(p[0].toLowerCase(Locale.ROOT)+p[2]),"目录symbol与完整身份冲突");}}need(roster.equals(primary),"完整目录与主自选不一致");JSONArray groups=s.getJSONArray("groups");need(groups.length()<=500,"分组超过500");Set<String>keys=new HashSet<>();for(int i=0;i<groups.length();i++){JSONObject g=groups.getJSONObject(i);String id=text(g,"groupId");need(!id.trim().isEmpty()&&id.length()<=256&&keys.add(id),"分组身份无效或重复");label(text(g,"name"));color(text(g,"color"));need(g.opt("readOnly") instanceof Boolean,"分组只读状态未明确");for(String member:ids(g.opt("memberIds"),true))need(primary.contains(member),"分组成员不在主自选完整目录");}return s;}
 static JSONObject management(JSONObject s)throws Exception{validate(s);JSONArray roster=new JSONArray(),raw=s.getJSONArray("instruments");for(int i=0;i<raw.length();i++){JSONObject r=raw.getJSONObject(i),row=object("id",r.get("id"),"name",r.get("name"));if(r.has("symbol"))row.put("symbol",r.get("symbol"));roster.put(row);}return object("schema",s.get("schema"),"revision",s.get("revision"),"mainIds",s.get("mainIds"),"groups",s.get("groups"),"instruments",roster);}
 static String fingerprint(JSONObject s)throws Exception{JSONObject m=management(s);m.remove("revision");return hash(m);}
 static int groupIndex(JSONArray gs,String id)throws Exception{for(int i=0;i<gs.length();i++)if(text(gs.getJSONObject(i),"groupId").equals(id))return i;return -1;}
 static JSONArray move(JSONArray a,int from,int to)throws Exception{need(from>=0&&from<a.length()&&to>=0&&to<a.length(),"排序位置已失效");List<Object>list=new ArrayList<>();for(int i=0;i<a.length();i++)list.add(a.get(i));Object v=list.remove(from);list.add(to,v);return new JSONArray(list);}
 static int position(JSONObject op)throws Exception{Object n=op.opt("to");need(n instanceof Number&&((Number)n).doubleValue()==((Number)n).intValue(),"排序位置需整数");return ((Number)n).intValue();}
 static JSONObject apply(JSONObject input,JSONObject op)throws Exception{JSONObject s=copy(validate(input));String kind=text(op,"op"),id=text(op,"groupId");JSONArray gs=s.getJSONArray("groups");int at=groupIndex(gs,id);if(kind.equals("addGroup")){need(at<0,"新分组身份已存在");gs.put(object("groupId",id,"name",text(op,"name"),"color",text(op,"color"),"readOnly",false,"memberIds",new JSONArray()));}else{need(at>=0,"分组不存在");JSONObject g=gs.getJSONObject(at);need(!g.getBoolean("readOnly"),"此来源分组只读，未写云端或本地副本");if(kind.equals("deleteGroup"))gs.remove(at);else if(kind.equals("moveGroup"))gs=move(gs,at,position(op));else{if(kind.equals("renameGroup"))g.put("name",text(op,"name"));else if(kind.equals("setColor"))g.put("color",text(op,"color"));else{JSONArray ms=g.getJSONArray("memberIds");String mid=text(op,"instrumentId");need(ids(s.get("mainIds"),true).contains(mid),"证券必须是当前主自选完整身份");int index=-1;for(int i=0;i<ms.length();i++)if(ms.getString(i).equals(mid))index=i;if(kind.equals("addMember")){need(index<0,"此证券已在该组；不会去重其它组");ms.put(mid);}else if(kind.equals("removeMember")){need(index>=0,"成员已不在该组");ms.remove(index);}else if(kind.equals("moveMember"))ms=move(ms,index,position(op));else need(false,"操作不支持");g.put("memberIds",ms);}gs.put(at,g);}}s.put("groups",gs);return validate(s);}
 static void transition(JSONObject base,JSONObject draft)throws Exception{validate(base);validate(draft);need(equal(base.get("mainIds"),draft.get("mainIds"))&&equal(base.get("instruments"),draft.get("instruments")),"分组操作不得改主自选或报价原文");JSONObject a=copy(base),b=copy(draft);a.remove("groups");b.remove("groups");need(equal(a,b),"分组操作不得改快照其它元数据");JSONArray old=base.getJSONArray("groups"),next=draft.getJSONArray("groups");for(int i=0;i<old.length();i++){JSONObject g=old.getJSONObject(i);int at=groupIndex(next,text(g,"groupId"));if(g.getBoolean("readOnly"))need(at>=0&&equal(g,next.get(at)),"只读来源分组被修改");if(at>=0){JSONObject before=copy(g),after=copy(next.getJSONObject(at));for(String k:new String[]{"name","color","memberIds"}){before.remove(k);after.remove(k);}need(equal(before,after),"分组身份/来源/只读元数据不得重写");}}for(int i=0;i<next.length();i++){JSONObject g=next.getJSONObject(i);if(groupIndex(old,text(g,"groupId"))<0){need(!g.getBoolean("readOnly"),"新增本地组不得伪造只读来源");Set<String>keys=new HashSet<>();g.keys().forEachRemaining(keys::add);need(keys.equals(new HashSet<>(Arrays.asList("color","groupId","memberIds","name","readOnly"))),"新组含非本模块字段");}}}
 static JSONObject prepare(JSONObject base,JSONObject draft,JSONObject current)throws Exception{transition(base,draft);validate(current);need(text(current,"revision").equals(text(base,"revision"))&&fingerprint(current).equals(fingerprint(base)),"自选配置或证券目录已并发变化；保留草稿，请重读后重做");JSONArray changes=new JSONArray(),old=base.getJSONArray("groups"),next=draft.getJSONArray("groups"),beforeOrder=new JSONArray(),afterOrder=new JSONArray();for(int i=0;i<old.length();i++)beforeOrder.put(old.getJSONObject(i).get("groupId"));for(int i=0;i<next.length();i++)afterOrder.put(next.getJSONObject(i).get("groupId"));for(int i=0;i<old.length();i++){JSONObject g=old.getJSONObject(i);String id=text(g,"groupId");int at=groupIndex(next,id);if(at<0)changes.put(object("kind","deleteGroup","groupId",id,"before",g,"after",JSONObject.NULL));else if(!equal(g,next.get(at)))changes.put(object("kind","editGroup","groupId",id,"before",g,"after",next.get(at)));}for(int i=0;i<next.length();i++){JSONObject g=next.getJSONObject(i);if(groupIndex(old,text(g,"groupId"))<0)changes.put(object("kind","addGroup","groupId",g.get("groupId"),"before",JSONObject.NULL,"after",g));}if(!equal(beforeOrder,afterOrder))changes.put(object("kind","groupOrder","before",beforeOrder,"after",afterOrder));return object("schema","watchlist-workspace-change/v1","expectedRevision",base.get("revision"),"expectedFingerprint",fingerprint(base),"groups",next,"mainIds",base.get("mainIds"),"changes",changes,"noChange",changes.length()==0);}
 static JSONObject receipt(JSONObject base,JSONObject draft,JSONObject saved)throws Exception{validate(saved);need(!equal(saved.get("revision"),base.get("revision"))&&equal(saved.get("groups"),draft.get("groups"))&&equal(saved.get("mainIds"),base.get("mainIds")),"保存回执未确认请求的完整分组或新版本，未宣称保存成功");JSONObject wanted=management(draft),actual=management(saved);wanted.remove("revision");actual.remove("revision");need(equal(wanted,actual),"保存回执证券目录已变化，未宣称成功");return saved;}
 // Host calls while holding its own atomic configuration lock/transaction.
 static JSONObject acceptChange(JSONObject current,JSONObject change,String nextRevision)throws Exception{validate(current);need(text(change,"schema").equals("watchlist-workspace-change/v1")&&text(change,"expectedRevision").equals(text(current,"revision"))&&text(change,"expectedFingerprint").equals(fingerprint(current)),"宿主保存时版本或配置并发变化，未覆盖");JSONObject requested=copy(current).put("groups",change.opt("groups"));need(equal(prepare(current,requested,current),change),"变更包与权威当前配置不一致，未采用伪造差异");if(change.getBoolean("noChange"))return copy(current);need(!nextRevision.trim().isEmpty()&&!nextRevision.equals(text(current,"revision")),"保存需明确新配置版本");requested.put("revision",nextRevision);return validate(requested);}
 static String describe(JSONObject p)throws Exception{StringBuilder out=new StringBuilder(p.getBoolean("noChange")?"没有配置变化；不会调用保存。\n":"待确认的本机分组变更：\n");JSONArray cs=p.getJSONArray("changes");for(int i=0;i<cs.length();i++){JSONObject c=cs.getJSONObject(i);if(c.getString("kind").equals("groupOrder"))out.append("组顺序：").append(canonical(c.get("before"))).append(" → ").append(canonical(c.get("after"))).append('\n');else{out.append(c.getString("kind").equals("addGroup")?"新建分组":c.getString("kind").equals("deleteGroup")?"删除分组":"修改分组").append(" · ").append(c.getString("groupId")).append('\n');JSONObject a=c.optJSONObject("before"),b=c.optJSONObject("after");if(a==null)a=new JSONObject();if(b==null)b=new JSONObject();out.append("名称：").append(a.optString("name","")).append(" → ").append(b.optString("name","")).append("\n识别色：").append(a.optString("color","")).append(" → ").append(b.optString("color","")).append("\n成员及顺序：").append(canonical(a.opt("memberIds"))).append(" → ").append(canonical(b.opt("memberIds"))).append('\n');}}return out.append("主自选未删除；其它组成员未连带删除；报价涨跌色未修改。\n").toString();}
}
